        node: &Node,
        parent: Option<u32>,
        index: usize,
        guest: &mut Guest<'_>,
        out: &mut usize,
    ) -> Result<(), crate::RingError> {
        let component_type = component_type_id(&node.component);

        let text_borrowed = match &node.component {
            Component::Text { text } => Some(text.as_str()),
            Component::Button { label } => Some(label.as_str()),
